  let mixB = mix(u.col3, u.col4, v1);
  var col = mix(mixA, mixB, v2);

  // Organic variation from warp fields
  let accent = mix(u.col2, u.col3, 0.5);
  col = mix(col, accent, v3 * 0.15);

  // Highlights where waves/folds meet
  var fold = abs(n1 - n2);
